    print(f"Writing TMDB Movies dataset to {movies_path}...")
    with open(movies_path, "w", newline="", encoding="utf-8") as f_mov, \
         open(credits_path, "w", newline="", encoding="utf-8") as f_cred:
        
        mov_writer = csv.writer(f_mov)
        cred_writer = csv.writer(f_cred)

        mov_writer.writerow([
            "budget", "genres", "homepage", "id", "keywords", "original_language", 
            "original_title", "overview", "popularity", "production_companies", 
            "production_countries", "release_date", "revenue", "runtime", 
            "spoken_languages", "status", "tagline", "title", "vote_average", "vote_count"
        ])

        cred_writer.writerow(["movie_id", "title", "cast", "crew"])

        for row in DETAILED_MOVIES:
            (mid, title, budget, genres, homepage, keywords, lang, orig_title, 
             overview, pop, rel_date, rev, runtime, tagline, vote_avg, vote_cnt, cast, crew) = row
            
            mov_writer.writerow([
                budget, json.dumps(genres), homepage, mid, json.dumps(keywords), lang,
                orig_title, overview, pop, json.dumps([{"name": "Studio"}]), 
                json.dumps([{"name": "USA"}]), rel_date, rev, runtime, 
                json.dumps([{"name": "English"}]), "Released", tagline, title, vote_avg, vote_cnt
            ])

            cred_writer.writerow([mid, title, json.dumps(cast), json.dumps(crew)])

